// lib/relatorio.mjs — o resumo da venda mostrado no caixa.
import { calcularTotal } from './calculos.mjs';
import { aplicarCupom } from './descontos.mjs';

// Resumo de UMA venda: subtotal (soma dos itens), total (com o cupom
// aplicado) e desconto (a diferença). Sem cupom válido, desconto é 0.
// O desconto também é arredondado: subtrair dois números "sujos" deixa
// resto — 99.9 - 89.91 dá 9.990000000000009.
export function resumoDaVenda(itens, cupom) {
  const subtotal = calcularTotal(itens);
  const total = aplicarCupom(subtotal, cupom);
  const desconto = Math.round((subtotal - total) * 100) / 100;
  return { subtotal, total, desconto };
}

