import { test } from 'node:test';
import assert from 'node:assert/strict';
import { calcularSubtotal, calcularTotal } from './lib/calculos.mjs';
import { aplicarCupom } from './lib/descontos.mjs';
import { resumoDaVenda } from './lib/relatorio.mjs';

test('calcularSubtotal multiplica preco vezes quantidade mesmo quando chegam em texto', () => {
  assert.equal(calcularSubtotal({ preco: 10, quantidade: '2' }), 20);
  assert.equal(calcularSubtotal({ preco: '5.5', quantidade: 2 }), 11);
  assert.throws(() => calcularSubtotal({ preco: 10 }), /preco ou quantidade/);
});

test('calcularTotal soma os subtotais e devolve 0 para lista vazia', () => {
  const itens = [
    { preco: 15, quantidade: 1 },
    { preco: 6, quantidade: 2 },
  ];
  assert.equal(calcularTotal(itens), 27);
  assert.equal(calcularTotal([]), 0);
  assert.throws(() => calcularTotal('nao e lista'), /lista/);
});

test('aplicarCupom TECH10 arredonda os centavos e cupom desconhecido nao desconta', () => {
  // 29.97 * 0.9 dá 26.973 em ponto flutuante — o resultado certo é 26.97.
  assert.equal(aplicarCupom(29.97, 'TECH10'), 26.97);
  assert.equal(aplicarCupom(29.97, 'NAOEXISTE'), 29.97);
  assert.equal(aplicarCupom(29.97, undefined), 29.97);
});

test('aplicarCupom respeita o desconto de cada cupom', () => {
  assert.equal(aplicarCupom(50, 'TECH10'), 45);
  assert.equal(aplicarCupom(50, 'TECH20'), 40);
  assert.throws(() => aplicarCupom('50', 'TECH10'), /total/);
});

test('resumoDaVenda calcula subtotal, desconto e total com o cupom', () => {
  const itens = [
    { preco: 15, quantidade: 1 },
    { preco: 6, quantidade: 2 },
  ];
  assert.deepEqual(resumoDaVenda(itens, 'TECH10'), { subtotal: 27, total: 24.3, desconto: 2.7 });
});

test('resumoDaVenda sem cupom valido nao inventa desconto (nem com lista vazia)', () => {
  const itens = [
    { preco: 15, quantidade: 1 },
    { preco: 6, quantidade: 2 },
  ];
  assert.deepEqual(resumoDaVenda(itens, 'SEMCUPOM'), { subtotal: 27, total: 27, desconto: 0 });
  assert.deepEqual(resumoDaVenda([], 'TECH10'), { subtotal: 0, total: 0, desconto: 0 });
});
